library ieee;
use ieee.std_logic_1164.all;

-- Synthesis top level. No package pins: everything goes through the PS.
--
-- The PS7 block (generated by build.tcl as a Vivado block design) supplies:
--   FCLK_CLK0  -- the 33.333 MHz clock for the whole PL. Linux sets its rate.
--   PL_RESETN  -- active-low reset, from FCLK_RESET0_N through a proc_sys_reset
--   M_AXI_*    -- the PS's AXI GP0 master port, converted from AXI3 to
--                 AXI4-Lite in the block design. Mapped at 0x43C0_0000.
-- core_top holds everything else. In simulation, sim/ps7_stub_wrapper_sim.vhd
-- stands in for the PS7 block; tb_core_top drives core_top's AXI port directly.
Entity board_top is
    Generic (
        PULSE_SET : integer := 2   -- pulse constants, see src/pulse_config_pkg.vhd
        );
end board_top;

architecture behavior of board_top is

signal clk     : std_logic;
signal resetn  : std_logic_vector(0 downto 0);

signal araddr, awaddr        : std_logic_vector(31 downto 0);
signal arprot, awprot        : std_logic_vector(2 downto 0);
signal arready, arvalid      : std_logic;
signal awready, awvalid      : std_logic;
signal bready, bvalid        : std_logic;
signal bresp, rresp          : std_logic_vector(1 downto 0);
signal rdata, wdata          : std_logic_vector(31 downto 0);
signal rready, rvalid        : std_logic;
signal wready, wvalid        : std_logic;
signal wstrb                 : std_logic_vector(3 downto 0);

-- Port names are the ones Vivado's make_wrapper generates for the block
-- design in build.tcl (interface port M_AXI, plain ports FCLK_CLK0, PL_RESETN).
component ps7_stub_wrapper is
    Port ( FCLK_CLK0     : out std_logic;
           PL_RESETN     : out std_logic_vector(0 downto 0);
           M_AXI_araddr  : out std_logic_vector(31 downto 0);
           M_AXI_arprot  : out std_logic_vector(2 downto 0);
           M_AXI_arready : in  std_logic;
           M_AXI_arvalid : out std_logic;
           M_AXI_awaddr  : out std_logic_vector(31 downto 0);
           M_AXI_awprot  : out std_logic_vector(2 downto 0);
           M_AXI_awready : in  std_logic;
           M_AXI_awvalid : out std_logic;
           M_AXI_bready  : out std_logic;
           M_AXI_bresp   : in  std_logic_vector(1 downto 0);
           M_AXI_bvalid  : in  std_logic;
           M_AXI_rdata   : in  std_logic_vector(31 downto 0);
           M_AXI_rready  : out std_logic;
           M_AXI_rresp   : in  std_logic_vector(1 downto 0);
           M_AXI_rvalid  : in  std_logic;
           M_AXI_wdata   : out std_logic_vector(31 downto 0);
           M_AXI_wready  : in  std_logic;
           M_AXI_wstrb   : out std_logic_vector(3 downto 0);
           M_AXI_wvalid  : out std_logic );
end component;

component core_top is
    Generic (PULSE_SET : integer;
             K         : integer;
             L         : integer;
             TRAP_M    : integer);
    Port (aclk          : in  std_logic;
          aresetn       : in  std_logic;
          s_axi_awaddr  : in  std_logic_vector(16 downto 0);
          s_axi_awvalid : in  std_logic;
          s_axi_awready : out std_logic;
          s_axi_wdata   : in  std_logic_vector(31 downto 0);
          s_axi_wstrb   : in  std_logic_vector(3 downto 0);
          s_axi_wvalid  : in  std_logic;
          s_axi_wready  : out std_logic;
          s_axi_bresp   : out std_logic_vector(1 downto 0);
          s_axi_bvalid  : out std_logic;
          s_axi_bready  : in  std_logic;
          s_axi_araddr  : in  std_logic_vector(16 downto 0);
          s_axi_arvalid : in  std_logic;
          s_axi_arready : out std_logic;
          s_axi_rdata   : out std_logic_vector(31 downto 0);
          s_axi_rresp   : out std_logic_vector(1 downto 0);
          s_axi_rvalid  : out std_logic;
          s_axi_rready  : in  std_logic);
end component;

begin

    ps7: ps7_stub_wrapper
        port map ( FCLK_CLK0     => clk,
                   PL_RESETN     => resetn,
                   M_AXI_araddr  => araddr,
                   M_AXI_arprot  => arprot,
                   M_AXI_arready => arready,
                   M_AXI_arvalid => arvalid,
                   M_AXI_awaddr  => awaddr,
                   M_AXI_awprot  => awprot,
                   M_AXI_awready => awready,
                   M_AXI_awvalid => awvalid,
                   M_AXI_bready  => bready,
                   M_AXI_bresp   => bresp,
                   M_AXI_bvalid  => bvalid,
                   M_AXI_rdata   => rdata,
                   M_AXI_rready  => rready,
                   M_AXI_rresp   => rresp,
                   M_AXI_rvalid  => rvalid,
                   M_AXI_wdata   => wdata,
                   M_AXI_wready  => wready,
                   M_AXI_wstrb   => wstrb,
                   M_AXI_wvalid  => wvalid );

    -- The 128 KB window is decoded by the PS (the block design assigns it), so
    -- only the low 17 address bits reach core_top.
    core: core_top
        generic map ( PULSE_SET => PULSE_SET, K => 32, L => 56, TRAP_M => 5 )
        port map ( aclk          => clk,
                   aresetn       => resetn(0),
                   s_axi_awaddr  => awaddr(16 downto 0),
                   s_axi_awvalid => awvalid,
                   s_axi_awready => awready,
                   s_axi_wdata   => wdata,
                   s_axi_wstrb   => wstrb,
                   s_axi_wvalid  => wvalid,
                   s_axi_wready  => wready,
                   s_axi_bresp   => bresp,
                   s_axi_bvalid  => bvalid,
                   s_axi_bready  => bready,
                   s_axi_araddr  => araddr(16 downto 0),
                   s_axi_arvalid => arvalid,
                   s_axi_arready => arready,
                   s_axi_rdata   => rdata,
                   s_axi_rresp   => rresp,
                   s_axi_rvalid  => rvalid,
                   s_axi_rready  => rready );

end behavior;
